S = "Hakeem Force Academy"
QS = [
(S, "What is the centre of a circle?", ["A fixed point equidistant from every point on the circle", "The longest chord of the circle", "A point on the circumference", "The midpoint of any tangent"], 0, "The centre is the single fixed point inside a circle that is at the same distance from all points on the circumference. A circle has exactly one centre.", "The fixed distance from the centre to the circle is called the radius.", [3240, 1854]),
(S, "The distance from the centre of a circle to any point on its circumference is called the", ["Radius", "Diameter", "Chord", "Arc"], 0, "The radius is the constant distance from the centre to any point on the circle. The diameter is twice the radius.", "Diameter = 2 x radius.", [3368]),
(S, "The total distance around a circle is called its", ["Circumference", "Diameter", "Radius", "Area"], 0, "The boundary length of a circle is called its circumference. It equals 2 x pi x radius.", "The ratio of circumference to diameter is the constant pi, about 3.14159.", [926, 927, 3246]),
(S, "Which is the correct spelling?", ["Circumfrence", "Circumference", "Circumferance", "Circumferrence"], 1, "The word is spelt circum-fer-ence, from Latin meaning carrying around.", "Circumference comes from the Latin words circum (around) and ferre (to carry).", [3711]),
(S, "What do the five rings of the Olympic flag represent?", ["Five inhabited continents of the world", "Five Olympic sports", "Five founding nations", "Five Olympic ideals"], 0, "The five interlocked rings stand for the five inhabited continents joined by Olympism: Africa, the Americas, Asia, Europe and Oceania.", "The rings are blue, yellow, black, green and red on a white background, designed in 1913 and first flown in 1920.", [839, 444]),
(S, "To which country did Winston Churchill, the famous leader of World War II, belong?", ["United Kingdom", "United States", "France", "Canada"], 0, "Winston Churchill was British and served as Prime Minister of the United Kingdom from 1940 to 1945 and again from 1951 to 1955.", "Churchill won the Nobel Prize in Literature in 1953.", [250, 2783]),
(S, "The Khyber Pass connects Peshawar with which town of Pakistan?", ["Landi Kotal", "Kohat", "Mardan", "Swat"], 0, "The Khyber Pass runs from near Peshawar through Jamrud and Landi Kotal to the Torkham border with Afghanistan.", "Landi Kotal is the highest point of the pass and lies close to the Afghan border.", [18, 2730]),
(S, "Which are the three largest cities of Pakistan by population?", ["Karachi, Lahore, Faisalabad", "Karachi, Lahore, Rawalpindi", "Lahore, Islamabad, Karachi", "Karachi, Faisalabad, Multan"], 0, "In the 2023 census the most populous cities were Karachi, then Lahore, then Faisalabad.", "Karachi is the largest city and the capital of Sindh.", [2838]),
(S, "Basel is a city of which country?", ["Germany", "Austria", "Switzerland", "Belgium"], 2, "Basel lies on the River Rhine in north-west Switzerland, near the French and German borders.", "Basel is home to the Bank for International Settlements.", [1545]),
(S, "In which city is the Shahi Qila (Lahore Fort) located?", ["Delhi", "Lahore", "Agra", "Multan"], 1, "The Shahi Qila, also called the Lahore Fort, stands in the Walled City of Lahore. It was rebuilt in the Mughal era, notably under Akbar.", "The Lahore Fort and Shalimar Gardens were listed as UNESCO World Heritage Sites in 1981.", [2185]),
(S, "Which city of Pakistan is called the City of Lights?", ["Lahore", "Karachi", "Peshawar", "Quetta"], 1, "Karachi is nicknamed the City of Lights because of its lively nightlife and its bright, busy streets.", "Karachi is also called the Mini Pakistan for its diverse population.", [1148]),
(S, "How many Pakistani nuclear tests were carried out in total in May 1998?", ["Three", "Five", "Six", "Seven"], 2, "Pakistan conducted five tests on 28 May 1998 and one more on 30 May 1998, giving six in total.", "The tests were carried out in the Chagai district of Balochistan, and 28 May is observed as Youm-e-Takbeer.", [1785]),
(S, "What is the characteristic of the logarithm (base 10) of 2458.4?", ["2", "3", "4", "0"], 1, "The characteristic is the number of digits before the decimal point minus one. 2458.4 has 4 digits before the point, so the characteristic is 3.", "The decimal part of a logarithm is called the mantissa.", [3241]),
(S, "What is the characteristic of log 99.96?", ["0", "1", "2", "3"], 1, "99.96 has 2 digits before the decimal point, so its characteristic is 2 - 1 = 1.", "Since log 100 = 2, log 99.96 is just under 2, that is 1 plus a mantissa close to 1.", [3242]),
(S, "What is the characteristic of log 99.6?", ["2", "0", "1", "9"], 2, "99.6 has 2 digits before the decimal point, so its characteristic is 2 - 1 = 1.", "For numbers less than 1 the characteristic is negative.", [3243]),
(S, "In the sentence 'The movie was amazing', what part of speech is the word 'amazing'?", ["Noun", "Adjective", "Verb", "Adverb"], 1, "The word 'amazing' describes the noun 'movie', so it is an adjective.", "An adjective modifies a noun or pronoun.", [1608]),
(S, "What is a quantity that can change its value called in mathematics?", ["Constant", "Variable", "Coefficient", "Integer"], 1, "A variable is a symbol that stands for a quantity that can take different values. A constant keeps a fixed value.", "Letters such as x and y are commonly used as variables.", [2987]),
(S, "How many times has Pakistan won the Hockey Champions Trophy?", ["Two", "Three", "Four", "Five"], 1, "Pakistan won the Champions Trophy three times, in 1978, 1980 and 1994.", "Australia is the most successful team in the tournament history, with 14 titles.", [1915]),
(S, "Which country topped the medal table of the 2018 Asian Games in Jakarta?", ["India", "Japan", "China", "South Korea"], 2, "China won the most gold medals (132) and the most medals overall at the 2018 Asian Games.", "Japan finished second and South Korea third in 2018.", [5212]),
(S, "Which country is the current FIFA World Cup champion (2026)?", ["Germany", "Argentina", "Spain", "France"], 2, "Spain beat Argentina 1-0 after extra time in the 2026 final on 19 July 2026.", "The previous champion was Argentina in 2022, and Germany won in 2014.", [4911]),
(S, "Who is the Premier (Prime Minister) of China?", ["Li Keqiang", "Li Qiang", "Wen Jiabao", "Wang Yi"], 1, "Li Qiang has been Premier of the State Council of China since March 2023.", "His predecessor was Li Keqiang, who served from 2013 to 2023.", [4951]),
(S, "What was the Chauri Chaura incident of 1922?", ["A mob burned a police station and killed policemen, after which Gandhi suspended the Non-Cooperation Movement", "A massacre of unarmed people at a garden in Amritsar", "A mutiny of Indian soldiers in Meerut", "A salt march to the sea"], 0, "On 4 February 1922 at Chauri Chaura in Uttar Pradesh a crowd set fire to a police station, killing about 22 policemen. Gandhi then called off the Non-Cooperation Movement.", "The Jallianwala Bagh massacre happened earlier, in 1919.", [3885, 3886]),
(S, "What is the closest meaning of 'up to date'?", ["Outdated", "Modern", "Ancient", "Slow"], 1, "Up to date means current or modern, including the latest information or style.", "Its opposite is outdated or obsolete.", [3253]),
(S, "What is the closest meaning of the word 'cordial'?", ["Hostile", "Warm and friendly", "Bitter", "Rude"], 1, "Cordial means warm, friendly and polite.", "Cordial can also be a noun meaning a sweet fruit drink.", [3257]),
(S, "What is the closest meaning of the word 'cute'?", ["Ugly", "Attractive and charming", "Clumsy", "Angry"], 1, "Cute means pleasingly attractive or charming, especially in a small or sweet way.", "Synonyms include adorable and lovely.", [3258]),
]
